/**
 * The orders client as the `web-storefront` consumer writes it.
 *
 * This file is a **stand-in for code that does not belong to this repository**.
 * In a real setup it lives in the storefront's own tree, its pact is produced by
 * the storefront's own suite, and this API never sees it — see docs/pact.md on
 * what changes when a broker is introduced. It is here because a pact has to be
 * generated by *something*, and the two honest options are a consumer that runs
 * or a JSON file somebody hand-edits. A hand-edited pact is a fixture pretending
 * to be a contract: nothing proves the consumer would ever send what it claims,
 * and nothing notices when the pact drifts from the matching rules the Pact
 * specification actually applies.
 *
 * So it is written the way a consumer client is written, not the way a test
 * helper is: it owns its base URL, it sends its own `Authorization` header, and
 * it narrows each response to the fields the storefront reads. That last part is
 * the whole point of consumer-driven contracts — the pact records what *this*
 * consumer needs, and the provider is free to return more.
 */

/** One line of an order, as the storefront renders it. */
export interface StorefrontOrderItem {
  readonly sku: string;
  readonly quantity: number;
  readonly unitPriceMinor: number;
}

/** How the checkout is going, as the storefront's status badge reads it. */
export interface StorefrontFulfilment {
  readonly sagaId: string;
  readonly status: string | null;
  readonly step: string | null;
}

/**
 * An order, reduced to what the storefront puts on screen.
 *
 * Deliberately narrower than `OrderResponseDto`: the storefront never reads
 * `reservationId`, `paymentId` or `shipmentId`, so they are not in this type and
 * not in the pact. A field absent from a pact is a field the provider may change
 * freely, which is the property that stops contract tests from freezing an API.
 */
export interface StorefrontOrder {
  readonly id: string;
  readonly status: string;
  readonly items: readonly StorefrontOrderItem[];
  readonly totalMinor: number;
  readonly currency: string;
  readonly shippingCountry: string;
  readonly failureReason: string | null;
  readonly fulfilment: StorefrontFulfilment;
  readonly createdAt: string;
  readonly updatedAt: string;
}

/**
 * What the storefront sends at checkout.
 *
 * No prices: the provider reads those from its own catalogue, and a request that
 * carried its own would be a request that could name them.
 */
export interface StorefrontBasket {
  readonly items: readonly { readonly sku: string; readonly quantity: number }[];
  readonly shippingCountry: string;
}

/** A page of orders, as the storefront's infinite scroll consumes it. */
export interface StorefrontOrderPage {
  readonly items: readonly StorefrontOrder[];
  readonly nextCursor: string | null;
  readonly hasNextPage: boolean;
}

/** What the storefront shows when the API refuses a request. */
export class StorefrontApiError extends Error {
  constructor(
    readonly status: number,
    /** The provider's `error` field — a short, stable code the storefront switches on. */
    readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = "StorefrontApiError";
  }
}

interface Envelope<T> {
  readonly success: true;
  readonly data: T;
  readonly meta: { readonly timestamp: string; readonly version: string };
}

interface ErrorBody {
  readonly statusCode: number;
  readonly message: string | string[];
  readonly error: string;
}

export interface StorefrontOrdersClientOptions {
  readonly baseUrl: string;
  /** The access token the storefront holds for the signed-in customer. */
  readonly accessToken: string;
}

export class StorefrontOrdersClient {
  private readonly baseUrl: string;
  private readonly accessToken: string;

  constructor(options: StorefrontOrdersClientOptions) {
    // Trailing slashes are stripped so `baseUrl` from configuration and
    // `baseUrl` from a Pact mock server produce the same request path.
    this.baseUrl = options.baseUrl.replace(/\/+$/, "");
    this.accessToken = options.accessToken;
  }

  /** The order detail page. */
  async getOrder(id: string): Promise<StorefrontOrder> {
    const envelope = await this.get<Envelope<StorefrontOrder>>(
      `/v1/orders/${encodeURIComponent(id)}`,
    );
    return envelope.data;
  }

  /** The order history page. `cursor` is whatever the previous page returned. */
  async listOrders(
    options: { cursor?: string; limit?: number } = {},
  ): Promise<StorefrontOrderPage> {
    const query = new URLSearchParams();
    if (options.cursor !== undefined) query.set("cursor", options.cursor);
    if (options.limit !== undefined) query.set("limit", String(options.limit));
    const suffix = query.size === 0 ? "" : `?${query.toString()}`;
    const envelope = await this.get<Envelope<StorefrontOrderPage>>(`/v1/orders${suffix}`);
    return envelope.data;
  }

  /** The checkout button. */
  async placeOrder(basket: StorefrontBasket): Promise<StorefrontOrder> {
    const envelope = await this.send<Envelope<StorefrontOrder>>("POST", "/v1/orders", basket);
    return envelope.data;
  }

  private get<T>(path: string): Promise<T> {
    return this.send<T>("GET", path);
  }

  private async send<T>(method: string, path: string, body?: unknown): Promise<T> {
    const response = await fetch(`${this.baseUrl}${path}`, {
      method,
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${this.accessToken}`,
        ...(body === undefined ? {} : { "Content-Type": "application/json" }),
      },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });

    if (!response.ok) {
      const problem = (await response.json()) as ErrorBody;
      const message = Array.isArray(problem.message) ? problem.message.join(", ") : problem.message;
      throw new StorefrontApiError(response.status, problem.error, message);
    }

    return (await response.json()) as T;
  }
}
